def dump(batch):
    ids = {"B01": IDS_B01, "B02": IDS_B02, "B03": IDS_B03}[batch]
    for cid in ids:
        p = f"{P3}/inputs-dev12/{cid}.json"
        with open(p, encoding="utf-8") as f:
            d = json.load(f)
        print("="*80)
        print(cid, "| keys:", list(d.keys()))
        print(json.dumps(d, ensure_ascii=False)[:2600])

if __name__ == "__main__" and len(sys.argv) > 1 and sys.argv[1] == "dump":
    dump(sys.argv[2])

