# ================= WRITER =================
if __name__ == "__main__" and (len(sys.argv) == 1 or sys.argv[1] == "write"):
    outdir = f"{P3}/runs/round72/predictions"
    os.makedirs(outdir, exist_ok=True)
    for cid in ALL:
        rec = PRED[cid]
        assert rec["case_id"] == cid
        assert set(rec.keys()) == {"case_id", "prediction_text", "basis", "confidence", "trigger"}
        assert 0.0 <= rec["confidence"] <= 1.0
        assert set(rec["trigger"].keys()) == {"changed_main", "reserve_used", "disputed", "reason"}
        with open(f"{outdir}/{cid}.json", "w", encoding="utf-8") as f:
            json.dump(rec, f, ensure_ascii=False, indent=1)
    # verify by exact id list only (no directory enumeration)
    n = 0
    cm = ru = di = 0
    for cid in ALL:
        with open(f"{outdir}/{cid}.json", encoding="utf-8") as f:
            r = json.load(f)
        assert r["case_id"] == cid and r["prediction_text"] and r["basis"]
        n += 1
        cm += bool(r["trigger"]["changed_main"]); ru += bool(r["trigger"]["reserve_used"]); di += bool(r["trigger"]["disputed"])
    print(f"written_and_verified={n} changed_main={cm} reserve_used={ru} disputed={di}")
